import cpmpy as cp
import numpy as np
import json
import itertools

# Input data
N = 10

# Generate all possible degree sequences
possible_degrees = [i for i in range(1, N+1) if i % 3 == 0]
degree_sequences = list(itertools.combinations_with_replacement(possible_degrees, N))

# Filter degree sequences based on the sum of degrees
degree_sequences = [seq for seq in degree_sequences if sum(seq) % 12 == 0]

# Initialize the model
model = cp.Model()

# Initialize the adjacency matrix
adj_matrix = cp.intvar(0, 1, shape=(N, N), name="adj_matrix")

# Constraints for the adjacency matrix
for i in range(N):
    for j in range(N):
        if i == j:
            model += adj_matrix[i, j] == 0  # no self-loops
        elif i < j:
            model += adj_matrix[i, j] == adj_matrix[j, i]  # symmetric matrix

# Constraints for the degree sequences
for seq in degree_sequences:
    model += cp.sum([adj_matrix[i, j] for j in range(N) for i in range(N) if i < j]) == sum(seq) / 2  # sum of degrees
    for i in range(N):
        model += cp.sum([adj_matrix[i, j] for j in range(N)]) == seq[i]  # degree of each vertex

    # Constraints for diamond-free graph
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for l in range(N):
                    if i < j and k < l:
                        model += adj_matrix[i, j] + adj_matrix[i, k] + adj_matrix[i, l] + adj_matrix[j, k] + adj_matrix[j, l] + adj_matrix[k, l] <= 4  # at most 4 edges between 4 vertices

    # Solve the model
    if model.solve():
        solution = {'matrix': adj_matrix.value().tolist()}
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")
    model = cp.Model()  # reset the model for the next iteration
