# Define the four operations
operations = ['+2', '/8', '-3', '*7']

# Generate all possible permutations of operations
perms = list(itertools.permutations(operations))

# Initialize variables
m = cp.intvar(0, 100, name='m')  # my age
h = cp.intvar(0, 100, name='h')  # husband's age

# Model definition
model = cp.Model()

# Constraints
for p1 in perms:
    for p2 in perms:
        if p1 == p2:
            continue
        # Apply operations to my age
        x = m
        for op in p1:
            if op == '+2':
                x = x + 2
            elif op == '/8':
                x = x / 8
            elif op == '-3':
                x = x - 3
            elif op == '*7':
                x = x * 7
        # Apply operations to husband's age
        y = h
        for op in p2:
            if op == '+2':
                y = y + 2
            elif op == '/8':
                y = y / 8
            elif op == '-3':
                y = y - 3
            elif op == '*7':
                y = y * 7
        # Constraints
        model += (x == h)
        model += (y == m)
        # Solve the model
        if model.solve():
            solution = {'m': int(m.value()), 'h': int(h.value())}
            print(json.dumps(solution, indent=4))
            break
    else:
        continue
    break
else:
